import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = {
        ('COG2A', 'DLU13'), ('SRFQ16', 'DLU13'), ('DLU13', 'JGE8'),
        ('NFAM8', 'DLU13'), ('PUI17P', 'DLU13'), ('SRFQ16', 'JGE8'),
        ('COG2A', 'JGE8'), ('LGZ7', 'JGE8'), ('XLCJ18P', 'SRFQ16'),
        ('XLCJ18P', 'DLU13'), ('LGZ7', 'DLU13'), ('FVR14', 'YYNY2'),
        ('PUI17P', 'NFAM8'), ('SRFQ16', 'NFAM8'), ('COG2A', 'NFAM8'),
        ('PUI17P', 'JGE8'), ('PUI17P', 'SRFQ16'), ('LGZ7', 'COG2A'),
        ('OPQC2', 'JGE8'), ('PUI17P', 'COG2A')
    }

    # Build set of unique features to keep
    keep_features = set(feats.ids)
    for a, b in correlated_pairs:
        if a in keep_features and b in keep_features:
            # Remove one of each pair (prefer higher mean_y1-mean_y0)
            if abs(feats.y.mean() - feats.x[:, feats.column(a)].mean()) > \
               abs(feats.y.mean() - feats.x[:, feats.column(b)].mean()):
                keep_features.remove(b)
            else:
                keep_features.remove(a)

    # Filter features
    filtered_ids = tuple(f for f in feats.ids if f in keep_features)

    # Select drivers based on t-statistics and correlation with outcome
    drivers = []
    for i, fid in enumerate(filtered_ids):
        if feats.types[i] == 'expression':
            # Calculate t-statistic-like measure
            group1 = feats.x[feats.y == 1, feats.column(fid)]
            group0 = feats.x[feats.y == 0, feats.column(fid)]
            if len(group1) > 0 and len(group0) > 0:
                t_stat = (group1.mean() - group0.mean()) / (
                    np.sqrt(np.var(group1)/len(group1) + np.var(group0)/len(group0))
                )
                if abs(t_stat) > 2.0:
                    drivers.append(fid)

    # Sort by effect size (mean_y1-mean_y0) 
    drivers.sort(key=lambda x: abs(feats.x[:, feats.column(x)].mean() * (feats.y.mean() - (1-feats.y.mean()))), reverse=True)
    drivers = drivers[:min(MAX_DRIVERS, len(drivers))]

    # If no clear drivers, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build columns and products
    columns = list(filtered_ids)
    products = []

    # Add interaction terms between top drivers (limit to 3 interactions max)
    count = 0
    for i, d1 in enumerate(drivers):
        for j, d2 in enumerate(drivers[i+1:], i+1):
            if (d1, d2) not in correlated_pairs and (d2, d1) not in correlated_pairs:
                products.append((d1, d2))
                count += 1
                if count >= 3:
                    break
        if count >= 3:
            break

    # Simple weighted score using top features
    loadings = {}
    for fid in drivers:
        col_idx = feats.column(fid)
        # Weight by effect size (t-statistic)
        group1 = feats.x[feats.y == 1, col_idx]
        group0 = feats.x[feats.y == 0, col_idx]
        if len(group1) > 0 and len(group0) > 0:
            effect = abs(group1.mean() - group0.mean())
        else:
            effect = 0
        loadings[fid] = effect

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )
